fn not_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Using iterator zip to pair elements, then map to produce boolean vector
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x != y)
        .collect()
}